public final class CameraLogoInstrumentation extends Instrumentation {
    private static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    @Override public void onStart(){Bundle result=new Bundle();try{
        Context base=getTargetContext();check(base.getPackageName().equals("cn.sixnine.filmlog.media.tests"),"isolated test package");Context context=new WorkspaceContext(Workspace.root(base),UUID.randomUUID().toString());
        check(CameraLogos.all(context).size()==308,"308 reviewed logos");check(CameraLogos.find(context,"Nikon-history-1988")==null&&CameraLogos.find(context,"Olympus-history-3")==null,"user exclusions absent");
        for(CameraLogos.Logo l:CameraLogos.all(context)){android.graphics.Bitmap b=CameraLogos.image(context,l);check(b!=null&&b.getWidth()<=720&&b.getHeight()<=180,"bounded decodable logo "+l.id);}
        check(CameraLogos.find(context,"initial-Nikon").monochrome,"near-black Nikon logo follows theme");
        check(CameraLogos.suggest(context,"Nikon FE2").equals("initial-Nikon"),"FE2 uses brand, never FE");check(CameraLogos.suggest(context,"Nikon F3").equals("GT23/NIKON-F3"),"F3 exact");check(CameraLogos.suggest(context,"Ricoh GR1s").equals("initial-Ricoh"),"GR1s never GR1");check(CameraLogos.suggest(context,"Unknown body").isEmpty(),"unknown generic");
        for(CameraLogos.Logo l:CameraLogos.recommended(context,"Nikon FE2"))check(l.model.isEmpty()&&!l.kind.equals("子品牌字标"),"no similar-model or subbrand recommendation");
        LogStore logs=new LogStore(context);CatalogStore catalog=new CatalogStore(logs);String camera=catalog.saveCamera("","Nikon FE2","银色机身","35 mm","keep","良好",true,"initial-Nikon");String other=catalog.saveCamera("","Nikon FE2","黑色机身","35 mm","","",false,"");check(!camera.equals(other),"same model has independent stable identities");
        catalog.saveEntry(camera,"camera","银色机身","35 mm","changed note");check(catalog.entry(camera,"camera").cameraModel.equals("Nikon FE2")&&catalog.entry(camera,"camera").cameraLogo.equals("initial-Nikon"),"ordinary edits preserve camera metadata");int before=catalog.entries("camera",false).size();try{catalog.saveCamera("","Nikon FE2","","35 mm","","",false,"not-a-logo");throw new AssertionError("invalid logo accepted");}catch(IllegalArgumentException expected){}check(catalog.entries("camera",false).size()==before,"invalid save atomic");
        String roll=catalog.manual(UUID.randomUUID().toString(),"Geometry","Test film","银色机身",400,36,"35 mm",camera,"");for(int i=0;i<35;i++)logs.insert(roll,10000+i*1000,0,480,"denied","8","1/125","","","","");
        final LogStore store=logs;final Throwable[] failed={null};runOnMainSync(()->{try{for(int width:new int[]{320,375,414}){HomeRollCard card=new HomeRollCard(context,store,store.roll(roll),()->{},()->{},()->{});int px=Math.round((width-48)*context.getResources().getDisplayMetrics().density);card.measure(View.MeasureSpec.makeMeasureSpec(px,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED));card.layout(0,0,px,card.getMeasuredHeight());TextView count=card.findViewWithTag("dashboard-count");View windows=card.findViewWithTag("dashboard-windows");check(count.getText().toString().equals("35/36"),"one actual counter");AbsoluteSizeSpan[] spans=((Spanned)count.getText()).getSpans(0,count.length(),AbsoluteSizeSpan.class);check(spans.length==1&&spans[0].getSize()==Math.round(10*context.getResources().getDisplayMetrics().scaledDensity),"10sp denominator");check(windows.getTop()==0&&windows.getWidth()==card.getWidth(),"full-width top band "+width);check(((TextView)card.findViewWithTag("dashboard-camera-model")).getText().toString().equals("FE2"),"default model without duplicated brand");}}catch(Throwable bad){failed[0]=bad;}});if(failed[0]!=null)throw failed[0];
        check(CameraLogos.displayModel(context,"Nikon FE2",false).equals("FE2")&&CameraLogos.displayModel(context,"Olympus 35 DC",false).equals("35 DC")&&CameraLogos.displayModel(context,"My custom camera",false).equals("My custom camera")&&CameraLogos.displayModel(context,"Nikkormat FT2",false).equals("Nikkormat FT2"),"only safely delimited known brand stripped");
        catalog.saveCamera(camera,"Nikon FE2","银色机身","35 mm","changed note","良好",true,"initial-Nikon",true);check(catalog.entry(camera,"camera").cameraShowBrand&&!catalog.entry(other,"camera").cameraShowBrand,"per-camera preference independent");
        ByteArrayOutputStream bytes=new ByteArrayOutputStream();FilmBackup.write(context,logs,bytes);try(FilmBackup.Prepared archive=FilmBackup.inspect(context,new ByteArrayInputStream(bytes.toByteArray()))){check(archive.manifest.getInt("schema")==25,"backup24");FilmBackup.restore(context,logs,archive);int matches=0;for(CatalogStore.Entry e:catalog.entries("camera",false))if(e.cameraModel.equals("Nikon FE2")&&e.cameraLogo.equals("initial-Nikon")&&e.cameraShowBrand)matches++;check(matches==2,"restore retains model/logo and remaps stable owner ID");JSONObject row=archive.manifest.getJSONArray("catalog_entries").getJSONObject(0);row.put("camera_logo","invalid");int count=catalog.entries("camera",false).size();try{FilmBackup.restore(context,logs,archive);throw new AssertionError("invalid backup logo accepted");}catch(IOException expected){}check(catalog.entries("camera",false).size()==count,"invalid restore atomic");row.put("camera_logo","");for(Object badFlag:new Object[]{2,.5,"1",true}){row.put("camera_show_brand",badFlag);try{FilmBackup.validate(archive);throw new AssertionError("invalid display preference accepted");}catch(IOException expected){}}row.put("camera_show_brand",1);archive.manifest.put("schema",19);JSONArray entries=archive.manifest.getJSONArray("catalog_entries");for(int i=0;i<entries.length();i++){entries.getJSONObject(i).remove("camera_model");entries.getJSONObject(i).remove("camera_logo");}FilmBackup.normalizeCatalog(archive.manifest);for(int i=0;i<entries.length();i++)check(entries.getJSONObject(i).getString("camera_logo").isEmpty()&&entries.getJSONObject(i).getString("camera_model").isEmpty(),"legacy backup no invented logo identity");}
        SQLiteDatabase db=logs.getWritableDatabase();String sql;try(Cursor c=db.rawQuery("SELECT sql FROM sqlite_master WHERE name='catalog_entries'",null)){c.moveToFirst();sql=c.getString(0);}ArrayList<String> columns=new ArrayList<>();try(Cursor c=db.rawQuery("PRAGMA table_info(catalog_entries)",null)){while(c.moveToNext()){String name=c.getString(1);if(!name.equals("camera_model")&&!name.equals("camera_logo")&&!name.equals("camera_show_brand"))columns.add(name);}}
        db.beginTransaction();try{db.execSQL("ALTER TABLE catalog_entries RENAME TO camera19_fixture");db.execSQL(sql.replaceAll(",\\s*camera_(model|logo) TEXT NOT NULL DEFAULT ''","").replaceAll(",\\s*camera_show_brand INTEGER NOT NULL DEFAULT 0",""));String names=android.text.TextUtils.join(",",columns);db.execSQL("INSERT INTO catalog_entries("+names+") SELECT "+names+" FROM camera19_fixture");db.execSQL("DROP TABLE camera19_fixture");db.setVersion(18);db.setTransactionSuccessful();}finally{db.endTransaction();}logs.close();logs=new LogStore(context);catalog=new CatalogStore(logs);check(logs.getReadableDatabase().getVersion()==24&&catalog.entry(camera,"camera").name.equals("银色机身")&&catalog.entry(camera,"camera").notes.equals("changed note")&&catalog.entry(camera,"camera").cameraModel.isEmpty()&&catalog.entry(camera,"camera").cameraLogo.isEmpty()&&!catalog.entry(camera,"camera").cameraShowBrand&&logs.roll(roll).count==35&&catalog.detail(roll).camera.equals(camera),"real v18-to22 upgrade preserves old fields, records and IDs");logs.close();
        result.putString("stream","PASS: 308 assets; excluded variants absent; strict model/brand suggestions; camera IDs and atomic save; backup23/legacy19/atomic invalid restore; real database18-to22; native Newsreader26/10 and top-band/model display at320/375/414\n");finish(-1,result);
    }catch(Throwable bad){result.putString("stream",android.util.Log.getStackTraceString(bad));finish(0,result);}}
}
